ENV=dict(os.environ, AWS_REGION=REGION,AWS_DEFAULT_REGION=REGION,AWS_PAGER='',AWS_MAX_ATTEMPTS='1',AWS_IGNORE_CONFIGURED_ENDPOINT_URLS='true')
for k in list(ENV):
    if k.startswith('AWS_ENDPOINT_URL'): del ENV[k]
CAP={'region':REGION,'caller_account':ACCOUNT,'actor_arn':None,'prefix':PREFIX,'sources':[{'path':'/tmp/stackd_dashboards_authority_retry_probe.py','content':Path(__file__).read_text()},{'url':'https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/API_PutDashboard.html'}],'observations':[],'cleanup':[],'cleanup_verification':{},'evidence_boundaries':['Real native HTTPS calls through shared aws_cli.py; dashboard management operations only.','Only exact request-ID-correlated CloudTrail records are retained. Unmatched bounded observations do not establish nonlogging.','Credentials are removed before disk writes; gzip bodies are decoded only in memory.'], 'audit':{'matched_events':[],'objects':[]}}
if OUT.exists(): CAP['prior_attempts']=[json.loads(OUT.read_text())]
ACTOR=None; OWN={}; IDS={}; SEEN=set(); MATCHED=set()

def scrub(v):
    if isinstance(v,dict): return {k:('[REDACTED]' if k.lower() in ('accesskeyid','secretaccesskey','sessiontoken','securitytoken') else scrub(x)) for k,x in v.items()}
    if isinstance(v,list): return [scrub(x) for x in v]
    if isinstance(v,str): return re.sub(r'\b(?:AKIA|ASIA)[A-Z0-9]{16}\b','[REDACTED]',v)
    return v

def save(): OUT.write_text(json.dumps(scrub(CAP),indent=2)+'\n')
def call(label,service,operation,params,env=None,actor=None,cleanup=False,required=False):
    started=int(time.time()*1000)
    p=run(service,operation,params,env or ENV,options=['--debug','--no-paginate','--cli-connect-timeout','10','--cli-read-timeout','30'],timeout=50)
    r=result(p,debug=True); r.setdefault('output',{})
    headers={}
    for h in re.findall(r'Response headers: (\{[^\n]+\})',p.stderr):
        try: headers={k.lower():v for k,v in ast.literal_eval(h).items()}
        except (ValueError,SyntaxError): pass
    rid=next((headers[k] for k in ('x-amzn-requestid','x-amzn-request-id','x-amz-request-id') if k in headers),None)
    if not rid:
        m=re.findall(r'<RequestId>([^<]+)</RequestId>',p.stderr); rid=m[-1] if m else None
