                except (ValueError,SyntaxError,TypeError): pass
    ob={'label':label,'service':service,'operation':operation,'input':params,'request_started_ms':started,'caller_account':ACCOUNT,'actor_arn':actor or ACTOR,'region':(env or ENV).get('AWS_REGION',REGION),'result':scrub(r)}
    CAP['cleanup' if cleanup else 'observations'].append(ob)
    if rid: IDS[rid]=label
    save(); print(label+': '+r['code'],flush=True)
