    return r

def req(label,service,operation,params,**kw): return call(label,service,operation,params,required=True,**kw)['output']
def policy(statements): return json.dumps({'Version':'2012-10-17','Statement':statements})
def allow(actions,resources='*'): return {'Effect':'Allow','Action':actions,'Resource':resources}
def assume(label,statements,role=None):
    p={'RoleArn':role or OWN['role_arn'],'RoleSessionName':label,'DurationSeconds':3600}
    if statements is not None:p['Policy']=policy(statements)
    o=req('assume-'+label,'sts','assume-role',p)
    e=dict(ENV,AWS_ACCESS_KEY_ID=o['Credentials']['AccessKeyId'],AWS_SECRET_ACCESS_KEY=o['Credentials']['SecretAccessKey'],AWS_SESSION_TOKEN=o['Credentials']['SessionToken'])
    for k in ('AWS_PROFILE','AWS_DEFAULT_PROFILE'):e.pop(k,None)
    return e,o['AssumedRoleUser']['Arn']

def audit_poll():
    listing=req('audit-list-'+str(len(CAP['observations'])),'s3api','list-objects-v2',{'Bucket':OWN['bucket'],'Prefix':'owned/AWSLogs/'+ACCOUNT+'/CloudTrail/'})
    for obj in listing.get('Contents',[]):
        key=obj['Key']
        if key in SEEN or not key.endswith('.gz'):continue
        SEEN.add(key)
        started=int(time.time()*1000)
        o=S3.get_object(Bucket=OWN['bucket'],Key=key)
        body=o['Body'].read(); o['Body'].close()
        meta=o['ResponseMetadata']; r={'code':'Success','output':{k:v for k,v in o.items() if k not in ('Body','ResponseMetadata')},'http_status':meta['HTTPStatusCode'],'request_id':meta['RequestId']}
        # JSON dates are rendered by boto3, retained as native ISO timestamps.
        r['output']={k:(v.isoformat() if hasattr(v,'isoformat') else v) for k,v in r['output'].items()}
