        for event in json.loads(gzip.decompress(body)).get('Records',[]):
            rid=event.get('requestID'); label=IDS.get(rid)
            if label and (rid,event.get('eventID')) not in MATCHED:
                MATCHED.add((rid,event.get('eventID'))); CAP['audit']['matched_events'].append({'label':label,'event':scrub(event)});count+=1
