OPS={'put-dashboard':'PutDashboard','get-dashboard':'GetDashboard','list-dashboards':'ListDashboards','delete-dashboards':'DeleteDashboards'}
A=PREFIX+'-a';B=PREFIX+'-b'
ARN='arn:aws:cloudwatch::'+ACCOUNT+':dashboard/'+A
REGIONAL='arn:aws:cloudwatch:'+REGION+':'+ACCOUNT+':dashboard/'+A
BODY=json.dumps({'widgets':[{'type':'text','x':0,'y':0,'width':6,'height':3,'properties':{'markdown':'Owned audit body '+PREFIX}}]})
ROLES=[];SESSIONS={};DASHBOARDS=False
CAP['evidence_boundaries'].extend(['Multi-region classic trail with global service events; no account or organization settings changed.','Only two uniquely owned dashboard names are used; all ListDashboards inputs are prefix restricted.','Native source request/response audit fields are retained exactly except credential redaction; absence of a field is not replaced with an inferred value.'])
def inp(op,name=A):
    if op=='put-dashboard':return {'DashboardName':name,'DashboardBody':BODY}
    if op=='get-dashboard':return {'DashboardName':name}
    if op=='list-dashboards':return {'DashboardNamePrefix':PREFIX}
    return {'DashboardNames':[name]}
def cw(label,op,params=None,session=None,region=None):
    e,actor=SESSIONS[session] if session else (ENV,ACTOR)
    if region:e=dict(e,AWS_REGION=region,AWS_DEFAULT_REGION=region)
    return call(label,'cloudwatch',op,params if params is not None else inp(op),env=e,actor=actor)
def recreate(label):
    req(label,'cloudwatch','put-dashboard',inp('put-dashboard'))
def make_role(suffix,statements):
    name=PREFIX+'-'+suffix;ROLES.append(name)
    trust=policy([{'Effect':'Allow','Principal':{'AWS':ACTOR},'Action':'sts:AssumeRole'}])
    o=req('create-role-'+suffix,'iam','create-role',{'RoleName':name,'AssumeRolePolicyDocument':trust})
    req('policy-'+suffix,'iam','put-role-policy',{'RoleName':name,'PolicyName':'dashboard-authority','PolicyDocument':policy(statements)})
    return o['Role']['Arn']
try:
    identity=req('caller-identity','sts','get-caller-identity',{})
    if identity['Account']!=ACCOUNT:raise RuntimeError('Unexpected native account')
    ACTOR=identity['Arn'];CAP['actor_arn']=ACTOR;CAP['observations'][0]['actor_arn']=ACTOR
    OWN['bucket']=PREFIX+'-audit';OWN['trail']=PREFIX+'-trail'
    trailarn='arn:aws:cloudtrail:'+REGION+':'+ACCOUNT+':trail/'+OWN['trail']
    req('create-audit-bucket','s3api','create-bucket',{'Bucket':OWN['bucket'],'CreateBucketConfiguration':{'LocationConstraint':REGION}})
    bp=policy([{'Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':'s3:GetBucketAcl','Resource':'arn:aws:s3:::'+OWN['bucket'],'Condition':{'StringEquals':{'aws:SourceArn':trailarn}}},{'Effect':'Allow','Principal':{'Service':'cloudtrail.amazonaws.com'},'Action':'s3:PutObject','Resource':'arn:aws:s3:::'+OWN['bucket']+'/owned/AWSLogs/'+ACCOUNT+'/*','Condition':{'StringEquals':{'aws:SourceArn':trailarn,'s3:x-amz-acl':'bucket-owner-full-control'}}}])
    req('audit-bucket-policy','s3api','put-bucket-policy',{'Bucket':OWN['bucket'],'Policy':bp})
    req('create-audit-trail','cloudtrail','create-trail',{'Name':OWN['trail'],'S3BucketName':OWN['bucket'],'S3KeyPrefix':'owned','IncludeGlobalServiceEvents':True,'IsMultiRegionTrail':True,'EnableLogFileValidation':False,'IsOrganizationTrail':False})
    req('select-management-events','cloudtrail','put-event-selectors',{'TrailName':OWN['trail'],'EventSelectors':[{'ReadWriteType':'All','IncludeManagementEvents':True}]})
    req('start-audit-logging','cloudtrail','start-logging',{'Name':OWN['trail']})
    S3=boto3.client('s3',region_name=REGION)
    ALL=['cloudwatch:'+a for a in OPS.values()]
    OWN['role_arn']=make_role('broad',[allow(ALL)])
    identities={op:make_role('id-'+op.split('-')[0],[allow(['cloudwatch:'+action],ARN)]) for op,action in OPS.items()}
    regional_role=make_role('regional',[allow(ALL,REGIONAL)])
    deny_role=make_role('deny',[allow(ALL),{'Effect':'Deny','Action':ALL,'Resource':'*'}])
    time.sleep(30)
    DASHBOARDS=True
    recreate('readiness-put-marker')
