    cw('resource-tag-unmatched-get','get-dashboard',inp('get-dashboard',A),session='resource-tag')
    for op,role in identities.items():SESSIONS['id-'+op]=assume('id-'+op,None,role)
    SESSIONS['regional']=assume('identity-regional',None,regional_role)
    SESSIONS['identity-deny']=assume('identity-explicit-deny',None,deny_role)
    for op,action in OPS.items():
        # A single action is allowed by the identity policy, on the global named ARN.
        cw('identity-named-'+op,op,session='id-'+op)
        if op=='delete-dashboards':recreate('restore-after-identity-delete')
        cw('identity-ungranted-action-'+op,'get-dashboard' if op!='get-dashboard' else 'put-dashboard',session='id-'+op)
        cw('identity-regional-arn-'+op,op,session='regional')
        cw('identity-explicit-deny-'+op,op,session='identity-deny')
        for scope,res in [('named',ARN),('regional',REGIONAL),('wildcard','*')]:
            key='session-'+scope+'-'+op;SESSIONS[key]=assume(key,[allow(['cloudwatch:'+action],res)])
            cw(key,op,session=key)
            if op=='delete-dashboards' and scope!='regional':recreate('restore-after-'+key)
        key='session-explicit-deny-'+op
        SESSIONS[key]=assume(key,[allow(ALL),{'Effect':'Deny','Action':['cloudwatch:'+action],'Resource':'*'}])
        cw(key,op,session=key)
    # Named authority cannot mutate/read the other owned resource.
    for op in ('put-dashboard','get-dashboard','delete-dashboards'):
        cw('named-other-resource-'+op,op,inp(op,B),session='session-named-'+op)
    for ordering,names in [('allowed-first',[A,B]),('denied-first',[B,A])]:
        cw('mixed-implicit-deny-'+ordering,'delete-dashboards',{'DashboardNames':names},session='session-named-delete-dashboards')
        cw('after-mixed-implicit-'+ordering+'-a','get-dashboard',inp('get-dashboard',A))
        cw('after-mixed-implicit-'+ordering+'-b','get-dashboard',inp('get-dashboard',B))
    denyB='arn:aws:cloudwatch::'+ACCOUNT+':dashboard/'+B
    SESSIONS['mixed-explicit']=assume('mixed-explicit',[allow(['cloudwatch:DeleteDashboards']),{'Effect':'Deny','Action':['cloudwatch:DeleteDashboards'],'Resource':denyB}])
    cw('mixed-explicit-deny','delete-dashboards',{'DashboardNames':[A,B]},session='mixed-explicit')
    cw('after-mixed-explicit-a','get-dashboard',inp('get-dashboard',A))
    cw('after-mixed-explicit-b','get-dashboard',inp('get-dashboard',B))
    # Audit-only validation probes, not exhaustive dashboard body/lifecycle testing.
    cw('audit-validation-put-body','put-dashboard',{'DashboardName':A,'DashboardBody':'not-json'})
    cw('audit-validation-get-name','get-dashboard',{'DashboardName':PREFIX+'/invalid'})
    cw('audit-validation-list-token','list-dashboards',{'DashboardNamePrefix':PREFIX,'NextToken':'invalid-'+PREFIX})
    cw('audit-validation-delete-name','delete-dashboards',{'DashboardNames':[PREFIX+'/invalid']})
    cw('audit-cross-region-get','get-dashboard',region='eu-west-1')
    cw('audit-cross-region-list','list-dashboards',region='us-east-1')
    cw('audit-success-mixed-delete','delete-dashboards',{'DashboardNames':[A,B]})
    labels=[o['label'] for o in CAP['observations'] if o['service']=='cloudwatch']
    CAP['audit']['matrix_completed_ms']=int(time.time()*1000);save()
    missing=wait_audit(labels,900)
    CAP['audit']['unmatched_labels']=missing;CAP['audit']['delivery_window_seconds']=900
    CAP['evidence_boundaries'].append('Unmatched labels after the bounded delivery window are inconclusive, not evidence that validation failures are unlogged.')
