    CAP['probe_error']={'type':type(exc).__name__,'message':str(exc)};save()
finally:
    if DASHBOARDS:
        call('cleanup-dashboards','cloudwatch','delete-dashboards',{'DashboardNames':[A,B]},cleanup=True)
        for name in (A,B):
            r=call('verify-dashboard-'+name[-1]+'-absent','cloudwatch','get-dashboard',{'DashboardName':name},cleanup=True)
            CAP['cleanup_verification'][name]=r.get('http_status')==404 and r.get('output',{}).get('__type','').endswith('#DashboardNotFoundError')
        r=call('verify-dashboard-prefix-empty','cloudwatch','list-dashboards',{'DashboardNamePrefix':PREFIX},cleanup=True)
        CAP['cleanup_verification']['dashboard-prefix-empty']=r['code']=='Success' and r['output'].get('DashboardEntries')==[]
    for role in ROLES:
        call('cleanup-policy-'+role,'iam','delete-role-policy',{'RoleName':role,'PolicyName':'dashboard-authority'},cleanup=True)
        p=call('verify-policies-empty-'+role,'iam','list-role-policies',{'RoleName':role},cleanup=True)
        CAP['cleanup_verification'][role+'-policies']=p['code']=='Success' and p['output'].get('PolicyNames')==[]
        call('cleanup-role-'+role,'iam','delete-role',{'RoleName':role},cleanup=True)
        r=call('verify-role-absent-'+role,'iam','get-role',{'RoleName':role},cleanup=True)
        CAP['cleanup_verification'][role]=r['code']=='NoSuchEntity'
    if OWN.get('trail'):
        call('stop-audit-logging','cloudtrail','stop-logging',{'Name':OWN['trail']},cleanup=True)
        call('delete-audit-trail','cloudtrail','delete-trail',{'Name':OWN['trail']},cleanup=True)
        r=call('verify-trail-absent','cloudtrail','get-trail',{'Name':OWN['trail']},cleanup=True)
        CAP['cleanup_verification']['trail']=r['code']=='TrailNotFoundException'
    if OWN.get('bucket'):
        for attempt in range(5):
            p=call('cleanup-list-objects-'+str(attempt),'s3api','list-objects-v2',{'Bucket':OWN['bucket']},cleanup=True)
            objects=[{'Key':o['Key']} for o in p['output'].get('Contents',[])]
            if objects:call('cleanup-delete-objects-'+str(attempt),'s3api','delete-objects',{'Bucket':OWN['bucket'],'Delete':{'Objects':objects,'Quiet':False}},cleanup=True)
            else:
                CAP['cleanup_verification']['bucket-objects-empty']=p['code']=='Success';break
        call('delete-audit-bucket','s3api','delete-bucket',{'Bucket':OWN['bucket']},cleanup=True)
        r=call('verify-bucket-absent','s3api','head-bucket',{'Bucket':OWN['bucket']},cleanup=True)
        CAP['cleanup_verification']['bucket']=r.get('http_status')==404
    CAP['cleanup_verification']['all_verified']=bool(CAP['cleanup_verification']) and all(CAP['cleanup_verification'].values())
    save()
    print('Finished; cleanup='+str(CAP['cleanup_verification']['all_verified']),flush=True)

